t.script:
//
    // 1. Service Worker Registration
    if ('serviceWorker' in navigator) {
        navigator.serviceWorker.register('/jandalah/sw.js').then(function(reg) {
            console.log('Jandalah PWA Service Worker Registered!');
        }).catch(function(err) {
            console.warn('SW registration failed:', err);
        });
    }

    // 2. Smart Environment & Browser Detection
    var ua = navigator.userAgent || navigator.vendor || window.opera || '';
    var isStandalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
    var isIos = /iPad|iPhone|iPod/.test(ua) && !window.MSStream;
    var isCriOS = /CriOS/i.test(ua);
    var isInApp = /WhatsApp|FBAN|FBAV|Instagram|Line|Messenger/i.test(ua);
    var isAndroid = /Android/i.test(ua);
    var isDismissed = localStorage.getItem('jandalah_pwa_dismissed_v2');

    if (!isStandalone && !isDismissed) {
        var container = document.getElementById('pwa_smart_container');
        if (container) {
            container.classList.remove('d-none');
            if (isIos) {
                if (isInApp) {
                    var inappBox = document.getElementById('pwa_inapp_box');
                    if (inappBox) inappBox.classList.remove('d-none');
                } else if (isCriOS) {
                    var chromeBox = document.getElementById('pwa_ios_chrome_box');
                    if (chromeBox) chromeBox.classList.remove('d-none');
                } else {
                    var safariBox = document.getElementById('pwa_ios_safari_box');
                    if (safariBox) safariBox.classList.remove('d-none');
                }
            } else {
                var androidBox = document.getElementById('pwa_android_box');
                if (androidBox) androidBox.classList.remove('d-none');
            }
        }
    }

    // 3. Android PWA beforeinstallprompt handler
    var deferredPrompt = null;
    window.addEventListener('beforeinstallprompt', function(e) {
        e.preventDefault();
        deferredPrompt = e;
        if (!isStandalone && !isDismissed) {
            var container = document.getElementById('pwa_smart_container');
            var androidBox = document.getElementById('pwa_android_box');
            if (container) container.classList.remove('d-none');
            if (androidBox) androidBox.classList.remove('d-none');
        }
    });

    var btnAndroidInstall = document.getElementById('btn_pwa_android_install');
    if (btnAndroidInstall) {
        btnAndroidInstall.addEventListener('click', function() {
            if (deferredPrompt) {
                deferredPrompt.prompt();
                deferredPrompt.userChoice.then(function(choice) {
                    deferredPrompt = null;
                    dismissPwa();
                });
            } else {
                alert('لتثبيت التطبيق: اضغط على قائمة المتصفح (⋮) ثم اختر "تثبيت التطبيق" أو "إضافة إلى الشاشة الرئيسية".');
            }
        });
    }

    function dismissPwa() {
        var container = document.getElementById('pwa_smart_container');
        if (container) container.classList.add('d-none');
        localStorage.setItem('jandalah_pwa_dismissed_v2', '1');
    }

    function copyPortalUrl() {
        var currentUrl = window.location.origin + '/my';
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(currentUrl).then(function() {
                showCopyFeedback();
            }).catch(function() {
                fallbackCopyText(currentUrl);
            });
        } else {
            fallbackCopyText(currentUrl);
        }
    }

    function fallbackCopyText(text) {
        var tempInput = document.createElement('input');
        tempInput.value = text;
        document.body.appendChild(tempInput);
        tempInput.select();
        try {
            document.execCommand('copy');
            showCopyFeedback();
        } catch (err) {
            alert('رابط البوابة هو: ' + text);
        }
        document.body.removeChild(tempInput);
    }

    function showCopyFeedback() {
        var fbChrome = document.getElementById('copy_feedback_chrome');
        var fbInapp = document.getElementById('copy_feedback_inapp');
        if (fbChrome) fbChrome.classList.remove('d-none');
        if (fbInapp) fbInapp.classList.remove('d-none');
        setTimeout(function() {
            if (fbChrome) fbChrome.classList.add('d-none');
            if (fbInapp) fbInapp.classList.add('d-none');
        }, 4000);
    }

    // 4. Live Clock
    function updateClock() {
        var now = new Date();
        var timeStr = now.toLocaleTimeString('ar-SA', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
        var clockEl = document.getElementById('ess_live_clock');
        if (clockEl) clockEl.innerText = timeStr;
    }
    setInterval(updateClock, 1000);
    updateClock();

    // 5. Punch Functionality
    function toggleAttendance() {
        var btn = document.getElementById('btn_toggle_attendance');
        var btnText = document.getElementById('btn_toggle_text');
        var feedback = document.getElementById('attendance_feedback');

        btn.disabled = true;
        btnText.innerText = 'جارٍ تحديد الموقع...';
        feedback.className = 'mt-2 small fw-bold text-info text-center';
        feedback.innerText = 'يرجى الانتظار، جاري قراءة إحداثيات الموقع (GPS)...';

        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                function(pos) {
                    sendPunch(pos.coords.latitude, pos.coords.longitude);
                },
                function(err) {
                    console.warn('Geolocation error:', err.message);
                    feedback.className = 'mt-2 small text-warning text-center';
                    feedback.innerText = 'تعذر قراءة GPS بدقة، سيتم التسجيل عبر عنوان IP الحالي...';
                    sendPunch(null, null);
                },
                { timeout: 8000, enableHighAccuracy: true }
            );
        } else {
            sendPunch(null, null);
        }
    }

    function sendPunch(lat, lon) {
        var feedback = document.getElementById('attendance_feedback');
        var btn = document.getElementById('btn_toggle_attendance');
        var btnText = document.getElementById('btn_toggle_text');

        fetch('/my/attendance/toggle', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: "2.0",
                method: "call",
                params: {
                    latitude: lat,
                    longitude: lon,
                    browser: navigator.userAgent
                }
            })
        })
        .then(function(r) { return r.json(); })
        .then(function(res) {
            var result = res.result || {};
            if (result.status === 'success') {
                feedback.className = 'mt-2 small fw-bold text-success text-center';
                feedback.innerText = result.message;
                setTimeout(function() { window.location.reload(); }, 1200);
            } else {
                feedback.className = 'mt-2 small fw-bold text-danger text-center';
                feedback.innerText = result.message || 'حدث خطأ أثناء التسجيل';
                btn.disabled = false;
            }
        })
        .catch(function(err) {
            feedback.className = 'mt-2 small fw-bold text-danger text-center';
            feedback.innerText = 'خطأ في الاتصال بالخادم، يرجى المحاولة ثانية.';
            btn.disabled = false;
        });
    }
//
